?>
<nav class="marketing-tabs" aria-label="Marketing pages"><?php foreach(['overview','posts','banners','campaigns','links','newsletter','referrals'] as $t):?><a href="?page=marketing&amp;tab=<?= $t ?>" <?= $tab === $t ? 'aria-current="page"' : '' ?>><?= ucfirst($t) ?></a><?php endforeach;?></nav>
