<?php elseif($tab==='posts'):?><div class="marketing-admin-grid"><section class="marketing-card"><h2>New Post</h2><form class="marketing-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_post"><label>Title<input name="title" required></label><label>Slug<input name="slug"></label><label>Category<input name="category" value="Update"></label><label>Excerpt<textarea name="excerpt"></textarea></label><label>Body<textarea name="body" rows="10"></textarea></label><label>Status<select name="status"><option>draft</option><option>published</option></select></label><label>Publish at<input type="datetime-local" name="publish_at" value="<?=gmdate('Y-m-d\TH:i')?>"></label><button class="marketing-button">Save Post</button></form></section><section class="marketing-card"><h2>Posts</h2><table class="marketing-table"><?php foreach($data['posts'] as $p):?><tr><td><strong><?=velvet_marketing_escape((string)$p['title'])?></strong><br><small><?=velvet_marketing_escape((string)$p['status'])?></small></td><td><a href="<?=velvet_marketing_escape(base_url('blog/post.php?slug=' . rawurlencode((string)$p['slug'])))?>">View</a></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="collection" value="posts"><input type="hidden" name="id" value="<?=velvet_marketing_escape((string)$p['id'])?>"><button>Delete</button></form></td></tr><?php endforeach;?></table></section></div>
<?php elseif($tab==='banners'):?><div class="marketing-admin-grid"><section class="marketing-card"><h2>Promotion Banner</h2><form class="marketing-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_banner"><label>Text<input name="text" required></label><label>Link<input name="url"></label><label>Starts<input type="datetime-local" name="starts_at"></label><label>Ends<input type="datetime-local" name="ends_at"></label><label><input type="checkbox" name="enabled" value="1" checked style="width:auto"> Enabled</label><button class="marketing-button">Save Banner</button></form></section><section class="marketing-card"><h2>Scheduled Banners</h2><?php foreach($data['banners'] as $b):?><p><?=velvet_marketing_escape((string)$b['text'])?> — <?=!empty($b['enabled'])?'Enabled':'Disabled'?></p><?php endforeach;?></section></div>
<?php elseif($tab==='campaigns'):?><div class="marketing-admin-grid"><section class="marketing-card"><h2>Campaign Landing Page</h2><form class="marketing-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_page"><label>Title<input name="title" required></label><label>Slug<input name="slug"></label><label>Eyebrow<input name="eyebrow" value="Special Offer"></label><label>Body<textarea name="body" rows="6"></textarea></label><label>Button label<input name="cta_label" value="Join Now"></label><label>Button link<input name="cta_url" value="/membership/"></label><label>Starts<input type="datetime-local" name="starts_at"></label><label>Ends<input type="datetime-local" name="ends_at"></label><label><input type="checkbox" name="enabled" value="1" checked style="width:auto"> Enabled</label><button class="marketing-button">Save Page</button></form></section><section class="marketing-card"><h2>Email Campaign</h2><form class="marketing-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_campaign"><label>Subject<input name="subject" required></label><label>Preheader<input name="preheader"></label><label>Message<textarea name="body" rows="8"></textarea></label><label>Schedule<input type="datetime-local" name="scheduled_at"></label><input type="hidden" name="status" value="draft"><label><input type="checkbox" name="queue" value="1" style="width:auto"> Queue for active subscribers now</label><button class="marketing-button">Save Campaign</button></form></section></div>
